function sharedMask = getSharedCategoryMaskLocal(category_labels)

    % IMPORTANT: identify shared categories by their saved category labels
    % directly. Do not infer them from substrings, aliases, or regex rules.
    % Only these four categories are shared across the two neural groups.
    category_labels = reshape(toCellstrLocal(category_labels), 1, []);
    shared_labels = {'Across', 'Feedforward', 'Feedback', 'Ambiguous'};

    sharedMask = ismember(category_labels, shared_labels);

    % The only category that should remain group/area-specific is Within.
    withinMask = strcmp(category_labels, 'Within');

    unknownMask = ~(sharedMask | withinMask);
    if any(unknownMask)
        error(['Unexpected timescale category label(s): %s. Expected only ' ...
               'Across, Within, Feedforward, Feedback, and Ambiguous.'], ...
              strjoin(category_labels(unknownMask), ', '));
    end
end

function warnIfSharedCategoryGroupsDifferLocal(M)

    values = M.values;
    sharedMask = getSharedCategoryMaskLocal(M.labels.categories);
    sharedIdx = find(sharedMask);

    if isempty(sharedIdx) || size(values, 2) <= 1
        return;
    end

    mismatchCount = 0;

    switch char(M.meta.model_mode)
        case 'all_condition_model'
            numSessions = size(values, 1);
            numGroups = size(values, 2);

            for c = sharedIdx
                for s = 1:numSessions
                    refVals = canonicalizeValueVectorLocal(values{s, 1, c});
                    for g = 2:numGroups
                        testVals = canonicalizeValueVectorLocal(values{s, g, c});
                        if ~isequaln(refVals, testVals)
                            mismatchCount = mismatchCount + 1;
                        end
                    end
                end
            end

        case 'condition_specific_models'
            numSessions = size(values, 1);
            numGroups = size(values, 2);
            numCond = size(values, 3);

            for c = sharedIdx
                for p = 1:numCond
                    for s = 1:numSessions
                        refVals = canonicalizeValueVectorLocal(values{s, 1, p, c});
                        for g = 2:numGroups
                            testVals = canonicalizeValueVectorLocal(values{s, g, p, c});
                            if ~isequaln(refVals, testVals)
                                mismatchCount = mismatchCount + 1;
                            end
                        end
                    end
                end
            end
    end

    if mismatchCount > 0
        warning(['Shared across-category values differed across groups in %d ' ...
            'session/category slice(s). To avoid double counting, the plot ' ...
            'uses Group 1 as the canonical shared-latent distribution. ' ...
            'This can occur when a group-specific DSL filter selects ' ...
            'different shared latents. Raw group-wise values remain in the MAT file.'], ...
            mismatchCount);
    end
end

function vals = canonicalizeValueVectorLocal(vals)

    vals = reshape(vals, 1, []);
    vals = vals(isfinite(vals));
    vals = sort(vals);
end

function valsPlot = transformTimescaleForDisplayLocal(vals, regular_max, overflow_y)

    valsPlot = vals;
    valsPlot(valsPlot > regular_max) = overflow_y;
end

function [xt, xtLabs] = buildSessionTicksFromAllConditionXLocal(xPositions, session_labels)

    % xPositions dimensions: session x group x category
    numSessions = size(xPositions, 1);
    numGroups = size(xPositions, 2);
    numCat = size(xPositions, 3);

    xt = [];
    xtLabs = {};

    for c = 1:numCat
        for g = 1:numGroups
            for s = 1:numSessions
                x = xPositions(s, g, c);
                if isfinite(x)
                    xt(end + 1) = x; %#ok<AGROW>
                    xtLabs{end + 1} = session_labels{s}; %#ok<AGROW>
                end
            end
        end
    end
end

function [xt, xtLabs] = buildSessionTicksFromConditionXLocal(sessionCenters, session_labels)

    % sessionCenters dimensions: session x group x category
    numSessions = size(sessionCenters, 1);
    numGroups = size(sessionCenters, 2);
    numCat = size(sessionCenters, 3);

    xt = [];
    xtLabs = {};

    for c = 1:numCat
        for g = 1:numGroups
            for s = 1:numSessions
                x = sessionCenters(s, g, c);
                if isfinite(x)
                    xt(end + 1) = x; %#ok<AGROW>
                    xtLabs{end + 1} = session_labels{s}; %#ok<AGROW>
                end
            end
        end
    end
end

function plotPointCloudLocal(ax, x0, vals, colorVal, point_size, ...
    point_alpha, jitter_width)

    vals = reshape(vals, 1, []);
    vals = vals(isfinite(vals));

    if isempty(vals)
        return;
    end

    x = x0 + jitter_width * (rand(size(vals)) - 0.5);

    sc = scatter(ax, x, vals, point_size, colorVal, 'o', ...
        'filled', 'MarkerEdgeColor', 'none');

    try
        sc.MarkerFaceAlpha = point_alpha;
    catch
    end
end

function vals = cleanTimescaleValuesLocal(vals, use_log_y)

    vals = reshape(vals, 1, []);
    vals = vals(isfinite(vals));

    if use_log_y
        vals = vals(vals > 0);
    end
end

function applyTimescaleAxisLocal(ax, use_log_y, y_min, regular_max, ...
    tick_step, overflow_y, top_padding)

    if use_log_y
        error('Fixed overflow timescale axis requires use_log_y = false.');
    end

    set(ax, 'YScale', 'linear');

    regularTicks = y_min:tick_step:regular_max;
    yTicks = [regularTicks, overflow_y];

    tickLabels = arrayfun(@(x) sprintf('%g', x), regularTicks, ...
        'UniformOutput', false);
    tickLabels{end + 1} = sprintf('>%g', regular_max);

    set(ax, 'YTick', yTicks, 'YTickLabel', tickLabels);
    ylim(ax, [y_min, overflow_y + top_padding]);
end

function drawTimescaleDivisionLinesLocal(ax, division_lines, ...
    line_color, line_style, line_width)

    division_lines = reshape(double(division_lines), 1, []);
    division_lines = unique(division_lines(isfinite(division_lines)));

    if isempty(division_lines)
        return;
    end

    xLimits = xlim(ax);
    yLimits = ylim(ax);

    for k = 1:numel(division_lines)
        y = division_lines(k);

        if y < yLimits(1) || y > yLimits(2)
            continue;
        end

        plot(ax, xLimits, [y y], line_style, ...
            'Color', line_color, ...
            'LineWidth', line_width, ...
            'HandleVisibility', 'off');
    end
end

function drawVerticalGuidesLocal(ax, smallPositions, xPositions, drawCategorySeparators)

    yl = ylim(ax);

    smallPositions = unique(reshape(smallPositions, 1, []));
    smallPositions = smallPositions(isfinite(smallPositions));

    for k = 1:numel(smallPositions)
        xline(ax, smallPositions(k), ':', ...
            'Color', [0.82 0.82 0.82], ...
            'LineWidth', 0.7);
    end

    if drawCategorySeparators
        numDims = ndims(xPositions);
        numCat = size(xPositions, numDims);

        for c = 1:(numCat - 1)
            currVals = getSliceAlongLastDimLocal(xPositions, c);
            nextVals = getSliceAlongLastDimLocal(xPositions, c + 1);

            currVals = currVals(isfinite(currVals));
            nextVals = nextVals(isfinite(nextVals));

            if isempty(currVals) || isempty(nextVals)
                continue;
            end

            sepX = (max(currVals(:)) + min(nextVals(:))) / 2;

            xline(ax, sepX, '-', ...
                'Color', [0.55 0.55 0.55], ...
                'LineWidth', 0.9);
        end
    end

    ylim(ax, yl);
end

function sliceVals = getSliceAlongLastDimLocal(xPositions, idxLast)

    subs = repmat({':'}, 1, ndims(xPositions));
    subs{end} = idxLast;
    sliceVals = xPositions(subs{:});
end

function groupCenters = getGroupCentersFromXPositionsLocal(xPositions)

    numDims = ndims(xPositions);

    if numDims < 2
        error('xPositions must have at least 2 dimensions.');
    end

    groupDim = numDims - 1;
    catDim = numDims;

    numGroups = size(xPositions, groupDim);
    numCat = size(xPositions, catDim);

    groupCenters = nan(numGroups, numCat);

    for g = 1:numGroups
        for c = 1:numCat
            subs = repmat({':'}, 1, numDims);
            subs{groupDim} = g;
            subs{catDim} = c;

            vals = xPositions(subs{:});
            vals = vals(:);
            vals = vals(isfinite(vals));

            if isempty(vals)
                groupCenters(g, c) = NaN;
            else
                groupCenters(g, c) = mean(vals);
            end
        end
    end
end

function xLimits = getCenteredOuterCategoryXLimitsLocal(xPositions)

    % Keep the first and last category visually centered inside their
    % outer plot boundaries. Interior category boundaries are defined by
    % drawVerticalGuidesLocal as the midpoint between adjacent categories.
    % Therefore, mirror the nearest interior separator around the center of
    % the first/last category to obtain symmetric outer boundaries.

    numDims = ndims(xPositions);
    numCat = size(xPositions, numDims);

    allVals = xPositions(isfinite(xPositions));

    if isempty(allVals)
        xLimits = [0, 1];
        return;
    end

    if numCat == 1
        centerX = mean(allVals);
        halfWidth = max(0.45, 0.5 * (max(allVals) - min(allVals)) + 0.45);
        xLimits = [centerX - halfWidth, centerX + halfWidth];
        return;
    end

    categoryCenters = getCategoryCentersFromXPositionsLocal(xPositions);

    firstVals = getSliceAlongLastDimLocal(xPositions, 1);
    secondVals = getSliceAlongLastDimLocal(xPositions, 2);
    firstVals = firstVals(isfinite(firstVals));
    secondVals = secondVals(isfinite(secondVals));

    prevVals = getSliceAlongLastDimLocal(xPositions, numCat - 1);
    lastVals = getSliceAlongLastDimLocal(xPositions, numCat);
    prevVals = prevVals(isfinite(prevVals));
    lastVals = lastVals(isfinite(lastVals));

    if isempty(firstVals) || isempty(secondVals) || ...
            isempty(prevVals) || isempty(lastVals) || ...
            ~isfinite(categoryCenters(1)) || ~isfinite(categoryCenters(end))
        xLimits = [min(allVals) - 0.45, max(allVals) + 0.45];
        return;
    end

    firstSeparator = (max(firstVals(:)) + min(secondVals(:))) / 2;
    lastSeparator = (max(prevVals(:)) + min(lastVals(:))) / 2;

    leftLimit = 2 * categoryCenters(1) - firstSeparator;
    rightLimit = 2 * categoryCenters(end) - lastSeparator;

    % Safety fallback for an unexpected category ordering.
    if ~(isfinite(leftLimit) && isfinite(rightLimit) && leftLimit < rightLimit)
        xLimits = [min(allVals) - 0.45, max(allVals) + 0.45];
    else
        xLimits = [leftLimit, rightLimit];
    end
end

function categoryCenters = getCategoryCentersFromXPositionsLocal(xPositions)

    numDims = ndims(xPositions);
    numCat = size(xPositions, numDims);
    categoryCenters = nan(1, numCat);

    for c = 1:numCat
        vals = getSliceAlongLastDimLocal(xPositions, c);
        vals = vals(:);
        vals = vals(isfinite(vals));

        if ~isempty(vals)
            categoryCenters(c) = mean(vals);
        end
    end
end

function sessionCenters = getSessionCentersFromConditionSeparateXLocal(xPositions)

    % xPositions dimensions:
    % condition x session x group x category

    if ndims(xPositions) ~= 4
        error('xPositions must be condition x session x group x category.');
    end

    numSessions = size(xPositions, 2);
    numGroups = size(xPositions, 3);
    numCat = size(xPositions, 4);

    sessionCenters = nan(numSessions, numGroups, numCat);

    for s = 1:numSessions
        for g = 1:numGroups
            for c = 1:numCat
                vals = xPositions(:, s, g, c);
                vals = vals(:);
                vals = vals(isfinite(vals));

                if isempty(vals)
                    sessionCenters(s, g, c) = NaN;
                else
                    sessionCenters(s, g, c) = mean(vals);
                end
            end
        end
    end
end

function addNestedLabelsLocal(ax, groupCenters, groupLabels, ...
    categoryCenters, categoryLabels, use_log_y, groupColors, groupMarkerFontSize)

    if nargin < 7
        groupColors = [];
    end

    if nargin < 8 || isempty(groupMarkerFontSize)
        groupMarkerFontSize = max(10, ax.FontSize + 1);
    end

    reserveBottomSpaceLocal(ax, 0.08);

    yl = ylim(ax);

    if use_log_y
        logRange = log10(yl(2)) - log10(yl(1));
        yGroup = 10 .^ (log10(yl(1)) - 0.080 * logRange);
        yCat = 10 .^ (log10(yl(1)) - 0.160 * logRange);
    else
        yGroup = yl(1) - 0.080 * (yl(2) - yl(1));
        yCat = yl(1) - 0.160 * (yl(2) - yl(1));
    end

    groupTextHandles = gobjects(size(groupCenters));

    for c = 1:size(groupCenters, 2)
        for g = 1:size(groupCenters, 1)
            if g <= numel(groupLabels) && isfinite(groupCenters(g, c))
                groupTextHandles(g, c) = text(ax, groupCenters(g, c), yGroup, groupLabels{g}, ...
                    'HorizontalAlignment', 'center', ...
                    'VerticalAlignment', 'top', ...
                    'Interpreter', 'none', ...
                    'FontWeight', 'normal', ...
                    'Color', [0 0 0], ...
                    'Clipping', 'off');
            end
        end
    end

    % In all-condition plots, groupColors is supplied so the Within-area
    % labels also serve as the area legend: a colored bullet is placed
    % immediately before each black group label. Shared categories have NaN
    % groupCenters, so no area marker or area label is drawn there.
    if ~isempty(groupColors)
        groupColors = ensureColorRowsLocal(groupColors, size(groupCenters, 1));

        % Let MATLAB calculate text extents before positioning the bullets.
        drawnow;
        xRange = diff(xlim(ax));
        markerGap = 0.0035 * xRange;

        for c = 1:size(groupCenters, 2)
            for g = 1:size(groupCenters, 1)
                hText = groupTextHandles(g, c);
                if isgraphics(hText)
                    ext = get(hText, 'Extent');
                    markerX = ext(1) - markerGap;

                    text(ax, markerX, yGroup, '\bullet', ...
                        'HorizontalAlignment', 'right', ...
                        'VerticalAlignment', 'top', ...
                        'Interpreter', 'tex', ...
                        'FontSize', groupMarkerFontSize, ...
                        'FontWeight', 'bold', ...
                        'Color', groupColors(g, :), ...
                        'Clipping', 'off');
                end
            end
        end
    end

    for c = 1:numel(categoryLabels)
        text(ax, categoryCenters(c), yCat, categoryLabels{c}, ...
            'HorizontalAlignment', 'center', ...
            'VerticalAlignment', 'top', ...
            'Interpreter', 'none', ...
            'FontWeight', 'bold', ...
            'Clipping', 'off');
    end
end

function reserveBottomSpaceLocal(ax, frac)

    pos = ax.Position;

    if pos(4) > frac + 0.2
        ax.Position = [pos(1), pos(2) + frac, pos(3), pos(4) - frac];
    end
end

function addGroupLegendLocal(ax, group_labels, group_colors, point_size, legend_title)

    if nargin < 5
        legend_title = '';
    end

    numGroups = numel(group_labels);
    group_colors = ensureColorRowsLocal(group_colors, numGroups);
    h = gobjects(1, numGroups);

    for g = 1:numGroups
        h(g) = scatter(ax, nan, nan, point_size, group_colors(g, :), ...
            'o', 'filled', 'MarkerEdgeColor', 'none');
    end

    lgd = legend(ax, h, group_labels, ...
        'Location', 'southoutside', ...
        'Orientation', 'horizontal', ...
        'Interpreter', 'none');

    lgd.Box = 'off';

    if ~isempty(legend_title)
        lgd.Title.String = legend_title;
        lgd.Title.Interpreter = 'none';
        lgd.Title.FontWeight = 'normal';
    end
end

function addConditionLegendLocal(ax, condition_labels, condition_colors, point_size)

    numCond = numel(condition_labels);
    condition_colors = ensureColorRowsLocal(condition_colors, numCond);

    hCond = gobjects(1, numCond);

    for p = 1:numCond
        hCond(p) = scatter(ax, nan, nan, point_size, condition_colors(p, :), ...
            'o', 'filled', 'MarkerEdgeColor', 'none');
    end

    lgd = legend(ax, hCond, condition_labels, ...
        'Location', 'southoutside', ...
        'Orientation', 'horizontal', ...
        'Interpreter', 'none');

    lgd.Box = 'off';
    lgd.NumColumns = min(8, numCond);
end

function titleStr = makeFigureTitleLocal(M)

    titleStr = sprintf('%s | %s | %s | %s | %s', ...
        M.meta.data_content, ...
        M.meta.model_mode, ...
        M.meta.timescale_source, ...
        makeSelectionTitleLocal(M.meta.use_dsl_filter, M.meta.dsl_field), ...
        M.meta.plot_session_mode);
end

function s = makeSelectionTitleLocal(use_dsl_filter, dsl_field)

    if use_dsl_filter
        s = char(dsl_field);
    else
        s = 'all';
    end
end

function labels = makeSessionShortLabelsLocal(numSessions)

    labels = cell(1, numSessions);

    for s = 1:numSessions
        labels{s} = sprintf('S%d', s);
    end
end

function repeatedLabels = makeRepeatedSessionLabelsLocal(sessionLabels, numGroups, numCat)

    sessionLabels = sessionLabels(:);
    repeatedLabels = cell(numel(sessionLabels) * numGroups * numCat, 1);
    idx = 0;

    for c = 1:numCat
        for g = 1:numGroups
            for s = 1:numel(sessionLabels)
                idx = idx + 1;
                repeatedLabels{idx} = sessionLabels{s};
            end
        end
    end
end

function name = getSessionNameLocal(session_dir)

    [parent_dir, catgt_name] = fileparts(session_dir);
    [~, parent_name] = fileparts(parent_dir);

    name = sprintf('%s/%s', parent_name, catgt_name);
end

function tag = makeFileTagLocal(label)

    label = char(string(label));
    tag = lower(label);
    tag = regexprep(tag, '[^a-z0-9]+', '_');
    tag = regexprep(tag, '^_+|_+$', '');
end

function selection_tag = makeSelectionTagLocal(use_dsl_filter, dsl_field)

    if ~use_dsl_filter
        selection_tag = 'all';
    else
        selection_tag = makeFileTagLocal(dsl_field);
    end
end

function group_names = normalizeGroupNamesLocal(group_names)

    if isstring(group_names)
        group_names = cellstr(group_names(:)');
    elseif ischar(group_names)
        if size(group_names, 1) == 1
            group_names = {group_names};
        else
            group_names = reshape(cellstr(group_names), 1, []);
        end
    elseif iscell(group_names)
        group_names = reshape(group_names, 1, []);
    else
        error('group_names must be text or a cell array of text.');
    end

    if isempty(group_names)
        error('group_names cannot be empty.');
    end

    for g = 1:numel(group_names)
        value = group_names{g};

        if ~(ischar(value) || (isstring(value) && isscalar(value)))
            error('group_names{%d} must contain text.', g);
        end

        value = strtrim(char(string(value)));

        if isempty(value)
            error('group_names{%d} cannot be empty.', g);
        end

        group_names{g} = value;
    end
end

function [group_display_names, group_file_tags, group_mapping_tag] = ...
        buildGroupLabelsLocal(group_names)

    nGroups = numel(group_names);
    group_display_names = cell(1, nGroups);
    group_file_tags = cell(1, nGroups);

    for g = 1:nGroups
        group_display_names{g} = sprintf( ...
            'Group %d: %s', g, group_names{g});
        group_file_tags{g} = sprintf( ...
            'G%02d_%s', g, makeSafeGroupNameTagLocal(group_names{g}));
    end

    group_mapping_tag = strjoin(group_file_tags, '_');
end

function tag = makeSafeGroupNameTagLocal(group_name)

    tag = strtrim(char(string(group_name)));
    tag = regexprep(tag, '[^A-Za-z0-9_-]+', '_');
    tag = regexprep(tag, '_+', '_');
    tag = regexprep(tag, '^_+|_+$', '');

    if isempty(tag)
        tag = 'area';
    end
end

function validateGroupNameCountLocal(group_names, numGroups, context_text)

    if numel(group_names) ~= numGroups
        error(['group_names has %d entries, but %s contains %d groups. ' ...
               'The order of group_names must follow the saved group order.'], ...
              numel(group_names), context_text, numGroups);
    end
end

function labels = ensureGroupLabelsLocal(group_labels, numGroups)

    if numel(group_labels) ~= numGroups
        error(['The manual group-label list has %d entries, but the plotted ' ...
               'result contains %d groups.'], numel(group_labels), numGroups);
    end

    labels = reshape(group_labels, 1, []);
end

function colors = ensureColorRowsLocal(colors, nRows)

    if ~isempty(colors) && (size(colors, 2) ~= 3 || ...
            any(~isfinite(colors(:))) || any(colors(:) < 0) || ...
            any(colors(:) > 1))
        error('group_colors must be a finite N-by-3 RGB matrix in [0, 1].');
    end

    fallback = lines(nRows);
    nProvided = min(size(colors, 1), nRows);

    if nProvided > 0
        fallback(1:nProvided, :) = colors(1:nProvided, :);
    end

    colors = fallback;
end

function labels = toCellstrLocal(x)

    if iscell(x)
        labels = cell(size(x));
        for k = 1:numel(x)
            labels{k} = char(string(x{k}));
        end
        labels = reshape(labels, size(x));
    elseif isstring(x)
        labels = cellstr(x);
    elseif ischar(x)
        labels = cellstr(x);
    else
        error('Input cannot be converted to cellstr.');
    end
end


function tag = makePlotModeTagLocal(plot_session_mode)

    switch char(plot_session_mode)
        case 'pool_sessions'
            tag = 'pool_s';

        case 'separate_sessions'
            tag = 'separ_s';

        otherwise
            tag = makeFileTagLocal(plot_session_mode);
    end
end
